-- Chat history per user and module. The chat id is generated by the browser
-- (useChat id), so the row is created on the first saved exchange.

create type public.chat_module as enum ('documents', 'classification');

create table public.chats (
  id uuid primary key,
  user_id uuid not null default auth.uid() references public.profiles (id) on delete cascade,
  module public.chat_module not null,
  title text not null,
  context jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index chats_user_module_updated_idx
  on public.chats (user_id, module, updated_at desc);

-- `message` is the full AI SDK UIMessage ({ id, role, parts, metadata? }).
create table public.chat_messages (
  chat_id uuid not null references public.chats (id) on delete cascade,
  id text not null,
  position integer not null check (position >= 0),
  role text not null check (role in ('system', 'user', 'assistant')),
  message jsonb not null,
  created_at timestamptz not null default now(),
  primary key (chat_id, id)
);

create index chat_messages_chat_position_idx
  on public.chat_messages (chat_id, position);

alter table public.chats enable row level security;
alter table public.chat_messages enable row level security;

create policy "Approved users manage their own chats"
  on public.chats for all
  to authenticated
  using (user_id = auth.uid() and public.is_approved())
  with check (user_id = auth.uid() and public.is_approved());

create policy "Approved users manage messages of their own chats"
  on public.chat_messages for all
  to authenticated
  using (
    public.is_approved()
    and exists (
      select 1 from public.chats
      where chats.id = chat_messages.chat_id and chats.user_id = auth.uid()
    )
  )
  with check (
    public.is_approved()
    and exists (
      select 1 from public.chats
      where chats.id = chat_messages.chat_id and chats.user_id = auth.uid()
    )
  );
